import {renderCloudDocuments} from './cloud-documents.js';
import {adminAccounts,adminJobs,adminState,setAccountAccess,reviewNonDelivery,recordDemoPayment,decisionEligibility,approveDecision} from './admin-store.js?v=2';
let root,helpers,segments=[],activePage='overview';
const $=s=>root.querySelector(s);
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const date=value=>value?new Date(value).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const icon=file=>`<span class="a-icon" aria-hidden="true"><img src="assets/driver/${file}" alt=""></span>`;
const initials=name=>e(name.split(' ').map(part=>part[0]).slice(0,2).join(''));
const link=(text,path,cls='')=>`<a class="${cls}" href="#/admin/${path}">${text}</a>`;
const button=(text,action,id='',cls='btn outline')=>`<button type="button" class="${cls}" data-admin-action="${action}" data-id="${e(id)}">${text}</button>`;
const badge=(text,color='')=>`<span class="a-tag ${color}">${e(text)}</span>`;
const status=job=>badge(job.status,({Completed:'green',Cancelled:'red',Failed:'red',Accepted:'blue','In Progress':'amber','Picked Up':'amber',Pending:'purple'})[job.status]||'');
const payment=job=>badge(job.paymentLabel,job.decision?(job.decision.type==='refund'?'red':'green'):job.captured?'blue':'');
const person=(name,sub='')=>`<div class="a-person"><span class="a-initials">${initials(name)}</span><div><strong>${e(name)}</strong><small>${e(sub)}</small></div></div>`;
const heading=(eyebrow,title,description,actions='')=>`<header class="a-page-heading"><div><span class="a-eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="a-heading-actions">${actions}</div>`:''}</header>`;
const panel=(title,description,content,action='')=>`<section class="a-panel"><div class="a-panel-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div>${content}</section>`;
const empty=(title,text='')=>`<div class="a-empty"><strong>${title}</strong>${text}</div>`;
const callout=(title,text,color='')=>`<div class="a-callout ${color}"><strong>${title}</strong>${text}</div>`;
const breadcrumb=(text,path)=>`<div class="a-breadcrumb">${link(text,path)}<span>›</span><span>Details</span></div>`;
const summary=(name,value,cls='')=>`<div class="a-summary-row ${cls}"><span>${name}</span><strong>${value}</strong></div>`;
const currentJobs=()=>adminJobs(localStorage).filter(job=>!job.historical);
const nav=[['overview','Overview','de705.svg'],['customers','Customers','56705.svg'],['drivers','Drivers','c327b.svg'],['documents','Driver Documents','6c563.svg'],['deliveries','Deliveries','0d8a7.svg'],['payments','Payments','edbe9.svg'],['activity','Activity Log','7dd87.svg']];
const filters={};
export function renderAdmin(options){
 root=options.app;helpers=options.helpers;segments=options.segments||[];activePage=segments[0]||'overview';
 document.title='365 Trucking | Admin Portal';
 if(activePage==='customers'||activePage==='drivers')segments[1]?accountDetail(decodeURIComponent(segments[1])):accountsPage(activePage==='customers'?'Customer':'Driver');
 else if(activePage==='documents')documentsPage();
 else if(activePage==='deliveries')segments[1]?deliveryDetail(decodeURIComponent(segments[1])):deliveriesPage();
 else if(activePage==='payments')paymentsPage(segments[1]||'review');
 else if(activePage==='activity')activityPage();
 else overview();
 root.onclick=handleClick;
}
function documentsPage(){
 shell(heading('Verification','Driver Documents','Review license scans, insurance, identity and background-check documents.')+'<div id="admin-cloud-documents"></div>');
 const banner=root.querySelector('.a-demo-banner');banner.textContent='Private verification workspace · Uploads and review decisions are saved to Supabase.';
 renderCloudDocuments(root.querySelector('#admin-cloud-documents'),{admin:true,driverId:segments[1]?decodeURIComponent(segments[1]):null});
}
function refresh(){renderAdmin({app:root,segments,helpers})}
function shell(content){
 const label=nav.find(item=>item[0]===activePage)?.[1]||'Overview';
 root.innerHTML=`<div class="admin-app"><aside class="a-sidebar"><a class="a-brand" href="#/admin/overview"><img src="assets/branding/365-trucking-updated.png" alt="365 Trucking"><div><strong>Control Center</strong><small>Administration</small></div></a><p class="a-nav-label">Workspace</p><nav class="a-nav" aria-label="Admin navigation">${nav.map(([path,name,file])=>`<a href="#/admin/${path}" ${activePage===path?'class="active" aria-current="page"':''}>${icon(file)}${name}</a>`).join('')}</nav><div class="a-sidebar-foot"><p class="a-nav-label" style="margin:0">Switch portal</p><a href="#/dashboard">Customer portal <span>↗</span></a><a href="#/driver/dashboard">Driver portal <span>↗</span></a><small>365 Trucking · Admin demo</small></div></aside><button type="button" class="a-sidebar-overlay" data-admin-action="menu" aria-label="Close admin navigation"></button><div class="a-workspace"><header class="a-topbar"><div class="a-topbar-left"><button type="button" class="a-menu" data-admin-action="menu" aria-label="Toggle admin navigation" aria-expanded="false">☰</button><span>Workspace</span><span>/</span><strong>${label}</strong></div><div class="a-topbar-right"><span class="a-live-tag">Local demo</span><span class="a-admin-avatar">AD</span><div><strong>Administrator</strong><small>Operations team</small></div></div></header><main class="a-content"><aside class="a-demo-banner">${icon('bfdb3.svg')}<strong>Demo workspace</strong><span>Account changes and financial approvals are recorded on this device. No real payments or refunds are processed.</span></aside>${content}</main><footer class="a-footer"><span>© 2027 365 Trucking. All rights reserved.</span><span>Admin control center · Local workspace</span></footer></div></div>`;
}
function table(headers,rows,emptyText='No results found.'){
 return `<div class="a-table-wrap"><table class="a-table"><thead><tr>${headers.map(name=>`<th scope="col">${name}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">${empty(emptyText,'Try another search or filter.')}</td></tr>`}</tbody></table></div>`;
}
function deliveryRow(job){return `<tr><td>${link('<strong>'+e(job.displayId)+'</strong>','deliveries/'+encodeURIComponent(job.id),'text-btn')}<small>${job.sample?'Sample delivery':'Customer booking'}</small></td><td class="a-route-cell"><span>${e(job.pickup)}</span><span>→ ${e(job.dropoff)}</span></td><td>${e(job.customer)}<small>${e(job.driverName||'No driver assigned')}</small></td><td>${status(job)}</td><td><strong>${money(job.total)}</strong></td><td>${payment(job)}</td><td>${link('Review →','deliveries/'+encodeURIComponent(job.id),'text-btn')}</td></tr>`}
const deliveryHeaders=['Delivery','Route','Customer / Driver','Status','Amount','Payment',''];
function activityList(events){return events.length?`<ul class="a-activity">${events.map(item=>`<li>${icon(item.action.includes('refund')?'edbe9.svg':'7dd87.svg')}<div><strong>${e(item.action)}</strong><p>${e(item.label)}${item.amount?' · '+money(item.amount):''}</p><small>${date(item.at)} · ${e(item.actor)}</small></div></li>`).join('')}</ul>`:empty('No activity yet','Admin actions will appear here as you review accounts and payments.')}
function overview(){
 const accounts=adminAccounts(localStorage),jobs=currentJobs(),state=adminState(localStorage),queue=jobs.filter(job=>!job.decision&&(job.captured||job.status==='Completed'&&job.payment!=='Cash on Delivery'));
 const active=jobs.filter(job=>['Pending','Accepted','In Progress','Picked Up'].includes(job.status));
 const approved=Object.values(state.decisions),payoutTotal=approved.filter(d=>d.type==='payout').reduce((n,d)=>n+d.amount,0),refundTotal=approved.filter(d=>d.type==='refund').reduce((n,d)=>n+d.amount,0);
 shell(`${heading('Operations overview','Your business, at a glance.','Manage your community, keep deliveries moving, and review payments in one place.',link('Review payments','payments','btn'))}<div class="a-stats">${[['Customers',accounts.filter(a=>a.role==='Customer'&&a.status==='Active').length,'Active local and sample accounts','56705.svg'],['Drivers',accounts.filter(a=>a.role==='Driver'&&a.status==='Active').length,'Active driver accounts','c327b.svg'],['Active deliveries',active.length,'Pending, accepted, or in progress','0d8a7.svg'],['Awaiting review',queue.length,'Deliveries requiring financial review','edbe9.svg']].map(([label,total,sub,file])=>`<article class="a-stat"><div class="a-stat-top"><span>${label}</span>${icon(file)}</div><strong>${total}</strong><small>${sub}</small></article>`).join('')}</div><div class="a-grid">${panel('Payment review queue','Release earnings or resolve a customer refund.',queue.length?queue.slice(0,4).map(job=>`<div class="a-queue-row"><span class="a-initials">${initials(job.customer)}</span><div><strong>${e(job.displayId)}</strong><p>${e(job.status==='Completed'?'Driver payment review':job.status==='Cancelled'||job.status==='Failed'?'Customer refund review':'Delivery review required')} · ${e(job.customer)}</p></div><div class="a-queue-amount"><strong>${money(job.total)}</strong><small>${job.sample?'Sample funds':'Demo booking'}</small></div>${link('Review →','deliveries/'+encodeURIComponent(job.id))}</div>`).join(''):empty('You’re all caught up.','There are no financial decisions awaiting review.'),link('View all','payments'))}<div class="a-stack">${panel('Financial summary','Approved decisions in this demo workspace.',`<div class="a-panel-body">${summary('Driver payouts approved',money(payoutTotal))}${summary('Customer refunds approved',money(refundTotal))}${summary('Held payments awaiting decision',money(jobs.filter(j=>j.captured&&!j.decision).reduce((n,j)=>n+j.total,0)))}<div class="a-divider"></div><p style="font-size:11px;color:#9ca3af">Amounts are illustrative. No transfers have been sent.</p></div>`)}${panel('Quick actions','Jump to your day-to-day controls.',`<div class="a-panel-body"><div class="a-quick-links">${link(icon('56705.svg')+' Customers','customers')}${link(icon('c327b.svg')+' Drivers','drivers')}${link(icon('0d8a7.svg')+' Deliveries','deliveries')}${link(icon('7dd87.svg')+' Activity','activity')}</div></div>`)}</div></div><div class="a-grid">${panel('Recent deliveries','Customer bookings and finance samples.',table(deliveryHeaders,jobs.slice(0,6).map(deliveryRow)),link('View all','deliveries'))}${panel('Recent activity','A record of admin decisions.',`<div class="a-panel-body">${activityList(state.audit.slice(0,5))}</div>`,link('View log','activity'))}</div>`);
}
function toolbar({searchLabel,placeholder,statuses=[],sources=false}){return `<div class="a-toolbar"><div class="a-search"><input id="a-search" aria-label="${searchLabel}" placeholder="${placeholder}"></div><div class="a-filter-group">${statuses.length?`<select id="a-status-filter" aria-label="Filter by status"><option value="">All statuses</option>${statuses.map(s=>`<option>${s}</option>`).join('')}</select>`:''}${sources?'<select id="a-source-filter" aria-label="Filter by source"><option value="">All sources</option><option value="Local">Local accounts</option><option value="Sample">Sample accounts</option></select>':''}</div></div>`}
function listController({key,data,filter,renderRow,headers,emptyText}){
 const saved=filters[key]||{q:'',status:'',source:'',page:1};filters[key]=saved;
 $('#a-search').value=saved.q;if($('#a-status-filter'))$('#a-status-filter').value=saved.status;if($('#a-source-filter'))$('#a-source-filter').value=saved.source;
 function draw(){saved.q=$('#a-search').value;saved.status=$('#a-status-filter')?.value||'';saved.source=$('#a-source-filter')?.value||'';const results=data.filter(item=>filter(item,saved));const pages=Math.max(1,Math.ceil(results.length/10));saved.page=Math.min(saved.page,pages);const start=(saved.page-1)*10;
 $('#a-results').innerHTML=table(headers,results.slice(start,start+10).map(renderRow),emptyText)+`<div class="a-pagination"><span>Showing ${results.length?start+1:0}–${Math.min(start+10,results.length)} of ${results.length}</span><div><button type="button" data-admin-page="-1" ${saved.page===1?'disabled':''}>Previous</button><button type="button" data-admin-page="1" ${saved.page===pages?'disabled':''}>Next</button></div></div>`;
 }
 $('#a-search').oninput=()=>{saved.page=1;draw()};for(const id of ['#a-status-filter','#a-source-filter'])if($(id))$(id).onchange=()=>{saved.page=1;draw()};
 $('#a-results').onclick=event=>{const pageButton=event.target.closest('[data-admin-page]');if(pageButton){saved.page+=Number(pageButton.dataset.adminPage);draw()}};draw();
}
function accountsPage(role){
 const accounts=adminAccounts(localStorage).filter(account=>account.role===role),rolePath=role==='Customer'?'customers':'drivers',jobs=adminJobs(localStorage);
 shell(`${heading('Account management',role==='Customer'?'Customers':'Drivers',`Review ${role.toLowerCase()} accounts, remove access, and restore accounts when needed.`)}${role==='Driver'?link('Review registered driver documents →','documents','btn outline'):''}${toolbar({searchLabel:'Search '+role.toLowerCase()+' accounts',placeholder:'Search by name or email…',statuses:['Active','Removed'],sources:true})}<section class="a-panel" id="a-results"></section><p style="font-size:11px;color:#9ca3af;margin-top:16px">Removing an account disables its local portal access. Delivery and financial records are retained.</p>`);
 listController({key:rolePath,data:accounts,headers:[role,'Source','Deliveries','Account status','Actions'],emptyText:'No matching accounts.',filter:(account,f)=>`${account.name} ${account.email}`.toLowerCase().includes(f.q.toLowerCase())&&(!f.status||account.status===f.status)&&(!f.source||(f.source==='Local'?account.source==='Local profile':account.source==='Design sample')),renderRow:account=>`<tr><td>${person(account.name,account.email||'No email on sample record')}</td><td>${badge(account.source,account.source==='Local profile'?'blue':'')}</td><td>${jobs.filter(job=>role==='Customer'?job.customerId===account.id:job.driverId===account.id).length}</td><td>${badge(account.status,account.status==='Active'?'green':'red')}</td><td><div class="a-row-actions">${link('View',rolePath+'/'+encodeURIComponent(account.id),'text-btn')}${button(account.status==='Active'?'Remove account':'Restore account',account.status==='Active'?'remove-account':'restore-account',account.id,'')}</div></td></tr>`});
}
function accountDetail(id){
 const account=adminAccounts(localStorage).find(a=>a.id===id);if(!account){shell(heading('Account management','Account not found','Return to the accounts list to choose another account.'));return}
 const path=account.role==='Customer'?'customers':'drivers',jobs=adminJobs(localStorage).filter(job=>account.role==='Customer'?job.customerId===id:job.driverId===id),active=jobs.filter(j=>!['Completed','Cancelled','Failed'].includes(j.status));
 shell(`${breadcrumb(account.role==='Customer'?'Customers':'Drivers',path)}${heading('Account details',e(account.name),'Review this account and its delivery history.',button(account.status==='Active'?'Remove account':'Restore account',account.status==='Active'?'remove-account':'restore-account',id,account.status==='Active'?'btn outline':'btn'))}<div class="a-grid"><div class="a-stack"><section class="a-panel"><div class="a-account-detail"><span class="a-initials">${initials(account.name)}</span><div><h2>${e(account.name)}</h2><p>${e(account.email||'No email on sample record')}</p>${badge(account.role,'blue')} ${badge(account.status,account.status==='Active'?'green':'red')}</div></div><div class="a-panel-body" style="border-top:1px solid #f3f4f6"><div class="a-info-grid"><div class="a-info-item"><small>Account ID</small><strong>${e(id)}</strong></div><div class="a-info-item"><small>Source</small><strong>${e(account.source)}</strong></div></div><div class="a-lifecycle"><div><strong>${jobs.length}</strong><small>Total deliveries</small></div><div><strong>${active.length}</strong><small>Active deliveries</small></div><div><strong>${jobs.filter(j=>j.status==='Completed').length}</strong><small>Completed</small></div></div>${account.status==='Removed'?callout('Access removed',e(account.removal.reason)+'<br><small>'+date(account.removal.at)+'</small>','red'):callout('Active account','This account can access its local portal. Real account authentication is not connected.','green')}</div></section>${panel('Delivery history','Related deliveries are retained even when account access is removed.',table(deliveryHeaders,jobs.slice(0,20).map(deliveryRow),'No deliveries for this account.'))}</div><aside class="a-stack">${panel('Account controls','Changes are recorded in the activity log.',`<div class="a-panel-body"><p style="font-size:12px;color:#6b7280">Remove portal access when an account should no longer use the service. You can restore access later.</p><div class="a-action-stack">${button(account.status==='Active'?'Remove account access':'Restore account access',account.status==='Active'?'remove-account':'restore-account',id,account.status==='Active'?'btn outline':'btn')}</div></div>`)}${active.length?panel('Active deliveries',`${active.length} deliveries may need your attention.`,`<div class="a-panel-body">${callout('Review ongoing work','Removing access does not cancel deliveries or settle payments. Review the affected deliveries separately.','amber')}<div class="a-action-stack">${active.slice(0,4).map(job=>link(e(job.displayId)+' →','deliveries/'+encodeURIComponent(job.id),'btn outline')).join('')}</div></div>`):''}</aside></div>`);
}
function deliveriesPage(){
 shell(`${heading('Delivery management','Deliveries','Review delivery progress, completion, cancellations, and payment eligibility.')}${toolbar({searchLabel:'Search deliveries',placeholder:'Search delivery ID, customer, or route…',statuses:['Pending','Accepted','In Progress','Picked Up','Completed','Cancelled','Failed']})}<div class="a-filter-group" style="margin-bottom:20px"><label style="font-size:12px;color:#6b7280;display:flex;align-items:center;gap:8px"><input id="a-history" type="checkbox"> Include driver design history</label></div><section class="a-panel" id="a-results"></section>`);
 const draw=()=>{const data=adminJobs(localStorage).filter(j=>$('#a-history').checked||!j.historical);listController({key:'deliveries',data,headers:deliveryHeaders,renderRow:deliveryRow,emptyText:'No matching deliveries.',filter:(job,f)=>`${job.displayId} ${job.customer} ${job.pickup} ${job.dropoff}`.toLowerCase().includes(f.q.toLowerCase())&&(!f.status||job.status===f.status)})};$('#a-history').onchange=draw;draw();
}
function deliveryDetail(id){
 const job=adminJobs(localStorage).find(j=>j.id===id);if(!job){shell(heading('Deliveries','Delivery not found','Return to the deliveries list to select a record.'));return}
 const accounts=adminAccounts(localStorage),customer=accounts.find(a=>a.id===job.customerId),driver=accounts.find(a=>a.id===job.driverId),payoutError=decisionEligibility(job,'payout'),refundError=decisionEligibility(job,'refund');
 const checklist=[['Delivery completed',job.status==='Completed'],['Driver assigned',!!job.driverId],['Payment held',job.captured],['No prior payout or refund',!job.decision]];
 const decision=job.decision;
 shell(`${breadcrumb('Deliveries','deliveries')}${heading('Delivery review',e(job.displayId),`${job.sample?'Sample delivery':'Customer booking'} · ${e(job.date)} at ${e(job.time)}`,status(job))}<div class="a-grid"><div class="a-stack">${panel('Delivery overview','Customer, driver, and route information.',`<div class="a-panel-body"><div class="a-info-grid"><div class="a-info-item"><small>Customer</small>${customer?link(e(job.customer),'customers/'+encodeURIComponent(customer.id),'text-btn'):'<strong>'+e(job.customer)+'</strong>'}</div><div class="a-info-item"><small>Driver</small>${driver?link(e(driver.name),'drivers/'+encodeURIComponent(driver.id),'text-btn'):'<strong>'+e(job.driverName||'Not assigned')+'</strong>'}</div><div class="a-info-item"><small>Pickup location</small><p>${e(job.pickup)}</p></div><div class="a-info-item"><small>Drop-off location</small><p>${e(job.dropoff)}</p></div><div class="a-info-item"><small>Vehicle</small><strong>${e(job.vehicle)}</strong></div><div class="a-info-item"><small>Delivery status</small>${status(job)}</div></div><div class="a-divider"></div>${job.notes?`<div class="a-info-item"><small>Customer instructions</small><p>${e(job.notes)}</p></div>`:''}${job.status==='Completed'?callout('Delivery completed',job.completedAt?'Completion recorded '+date(job.completedAt)+'. Review completion before releasing funds.':'This is a completed design sample. Review it before recording a demo payout.','green'):job.review?callout('Non-delivery reviewed',e(job.review.reason)+'<br><small>'+date(job.review.at)+'</small>','red'):job.status==='Cancelled'?callout('Delivery cancelled','The delivery was cancelled. Review held funds before approving a customer refund.','amber'):callout('Delivery is not complete','Payment release is unavailable until the driver completes this delivery.')}</div>`)}${panel('Delivery review','Record non-delivery when the delivery was not made.',`<div class="a-panel-body">${job.status==='Completed'?callout('Completion recorded','A non-delivery refund cannot be approved for a completed delivery.'):job.review?`<div class="a-review-history"><strong>Non-delivery recorded</strong><p class="a-reason-value">${e(job.review.reason)}</p><p style="margin-top:8px">Reviewed ${date(job.review.at)}</p></div>`:`<p style="font-size:12px;color:#6b7280">Confirm what happened and record a reason. This marks the delivery as failed for the customer and driver and makes held funds eligible for refund review.</p><div class="a-action-stack">${job.decision?'':button('Record non-delivery','non-delivery',id,'btn outline')}</div>`}</div>`)}${panel('Review history','Admin actions for this delivery.',`<div class="a-panel-body">${activityList(adminState(localStorage).audit.filter(item=>item.entity===id).slice(0,8))}</div>`)}</div><aside class="a-stack">${panel('Payment summary','Demo held funds and approval status.',`<div class="a-panel-body">${summary('Payment method',e(job.payment))}${summary('Payment status',payment(job))}${summary('Booking amount',money(job.total))}${summary('Amount under review',money(job.total),'total')}${decision?`<div class="a-divider"></div>${callout(decision.type==='refund'?'Customer refund approved':'Driver payment approved',e(decision.reason)+'<br><small>'+date(decision.at)+' · '+e(decision.actor)+'</small>',decision.type==='refund'?'red':'green')}<p style="font-size:11px;color:#9ca3af;margin-top:12px">Recorded decision only. No money has been transferred.</p>`:`<p style="font-size:11px;color:#9ca3af">Demo decisions use the full held booking amount. Production driver fees and payout rules are not configured.</p>${!job.captured&&job.payment!=='Cash on Delivery'?`<div class="a-divider"></div>${callout('No payment held','The booking form does not collect money. Record a sample payment to test approvals.')}<div class="a-action-stack">${button('Record demo payment','capture',id,'btn outline')}</div>`:''}`}</div>`)}${panel('Driver payment approval','Release earnings after delivery completion.',`<div class="a-panel-body"><ul class="a-checklist">${checklist.map(([label,passed])=>`<li class="${passed?'passed':''}"><span>${passed?'✓':'–'}</span>${label}</li>`).join('')}</ul><div class="a-action-stack"><button type="button" class="btn" data-admin-action="payout" data-id="${e(id)}" ${payoutError?'disabled':''}>Approve driver payment</button></div>${payoutError?`<p class="d-auth-note">${e(payoutError)}</p>`:''}</div>`)}${panel('Customer refund','Refund held funds for a delivery that was not made.',`<div class="a-panel-body"><p style="font-size:12px;color:#6b7280">Refunds require a cancellation or reviewed non-delivery, held funds, and no earlier financial decision.</p><div class="a-action-stack"><button type="button" class="btn outline" data-admin-action="refund" data-id="${e(id)}" ${refundError?'disabled':''}>Approve customer refund</button></div>${refundError?`<p class="d-auth-note">${e(refundError)}</p>`:''}</div>`)}</aside></div>`);
}
function paymentsPage(tab){
 const all=currentJobs(),approved=all.filter(j=>j.decision?.type==='payout'),refunds=all.filter(j=>j.decision?.type==='refund'),review=all.filter(j=>!j.decision&&(j.captured||j.status==='Completed'&&j.payment!=='Cash on Delivery'));
 const options=[['review','Needs review',review],['payouts','Approved payouts',approved],['refunds','Approved refunds',refunds],['all','All payments',all]],selected=options.find(o=>o[0]===tab)||options[0];
 shell(`${heading('Financial controls','Payments & refunds','Review driver earnings after delivery and resolve refunds for non-deliveries.')}<div class="a-stats">${[['Held for review',money(all.filter(j=>j.captured&&!j.decision).reduce((n,j)=>n+j.total,0)),'Unsettled demo funds','edbe9.svg'],['Approved driver payouts',money(approved.reduce((n,j)=>n+j.decision.amount,0)),approved.length+' approved decisions','36ad5.svg'],['Approved customer refunds',money(refunds.reduce((n,j)=>n+j.decision.amount,0)),refunds.length+' approved decisions','a414e.svg'],['Awaiting review',review.length,'Delivery and payment checks','7dd87.svg']].map(([label,total,sub,file])=>`<article class="a-stat"><div class="a-stat-top"><span>${label}</span>${icon(file)}</div><strong>${total}</strong><small>${sub}</small></article>`).join('')}</div><div class="a-tabs">${options.map(([path,label,items])=>link(label+'<small>'+items.length+'</small>','payments/'+path,path===selected[0]?'active':'')).join('')}</div>${toolbar({searchLabel:'Search payments',placeholder:'Search delivery or customer…'})}<section class="a-panel" id="a-results"></section>`);
 listController({key:'payments-'+selected[0],data:selected[2],headers:['Delivery','Customer / Driver','Delivery status','Amount','Payment status','Actions'],emptyText:'No payments in this view.',filter:(job,f)=>`${job.displayId} ${job.customer} ${job.driverName}`.toLowerCase().includes(f.q.toLowerCase()),renderRow:job=>`<tr><td><strong>${e(job.displayId)}</strong><small>${job.sample?'Sample funds':'Customer booking'}</small></td><td>${e(job.customer)}<small>${e(job.driverName||'Not assigned')}</small></td><td>${status(job)}</td><td><strong>${money(job.total)}</strong></td><td>${payment(job)}</td><td>${link('Review →','deliveries/'+encodeURIComponent(job.id),'text-btn')}</td></tr>`});
}
function activityPage(){
 const events=adminState(localStorage).audit;
 shell(`${heading('Accountability','Activity log','Review account changes, delivery reviews, payout approvals, and refunds. Every action includes an administrator, time, and reason.')}${toolbar({searchLabel:'Search admin activity',placeholder:'Search action, account, delivery, or reason…'})}<section class="a-panel" id="a-results"></section>`);
 listController({key:'activity',data:events,headers:['Action','Account / Delivery','Reason','Amount','Administrator','Recorded'],emptyText:'No admin activity yet.',filter:(item,f)=>`${item.action} ${item.label} ${item.entity} ${item.reason}`.toLowerCase().includes(f.q.toLowerCase()),renderRow:item=>`<tr><td><strong>${e(item.action)}</strong></td><td>${e(item.label)}<small>${e(item.entity)}</small></td><td style="white-space:normal;min-width:200px;max-width:320px">${e(item.reason)}</td><td>${item.amount?money(item.amount):'—'}</td><td>${e(item.actor)}</td><td>${date(item.at)}</td></tr>`});
}
function actionDialog(kind,id){
 const accounts=adminAccounts(localStorage),jobs=adminJobs(localStorage),account=accounts.find(a=>a.id===id),job=jobs.find(j=>j.id===id),isAccount=kind==='remove-account'||kind==='restore-account',isFinance=kind==='payout'||kind==='refund';
 if(isAccount&&!account||!isAccount&&!job)return helpers.toast('This record could not be found.');
 const config={
  'remove-account':['Remove account?',`Remove ${account?.name}'s ${account?.role.toLowerCase()} portal access. Delivery and financial records will be retained.`, 'Remove account'],
  'restore-account':['Restore account?',`Restore ${account?.name}'s access to the ${account?.role.toLowerCase()} portal.`, 'Restore account'],
  'non-delivery':['Confirm non-delivery',`Record that ${job?.displayId} was not delivered. This will stop the driver workflow and enable refund review for held funds.`, 'Record non-delivery'],
  capture:['Record demo payment',`Record a sample held payment for ${job?.displayId}. This does not charge a card or collect money.`, 'Record demo payment'],
  payout:['Approve driver payment',`Approve ${money(job?.total)} for ${job?.driverName||'the assigned driver'} after reviewing this completed delivery.`, 'Approve payment'],
  refund:['Approve customer refund',`Approve a ${money(job?.total)} refund to ${job?.customer} for a delivery that was not made.`, 'Approve refund']
 }[kind];
 const dialog=document.createElement('dialog');dialog.className='a-dialog';dialog.setAttribute('aria-labelledby','a-dialog-title');
 dialog.innerHTML=`<form id="a-action-form"><header class="a-dialog-head"><div><h2 id="a-dialog-title">${config[0]}</h2><p>${e(isAccount?account.name:job.displayId)}</p></div><button type="button" class="a-dialog-close" aria-label="Close dialog">×</button></header><div class="a-dialog-body"><p style="font-size:13px;color:#4b5563;line-height:23px">${e(config[1])}</p>${!isAccount?`<div class="a-dialog-amount"><span>${kind==='refund'?'Refund amount':kind==='payout'?'Driver payment':kind==='non-delivery'?'Booking amount':'Sample held payment'}</span><strong>${money(job.total)}</strong></div>`:''}${isFinance?callout('Demo approval only','This records an approval in your local workspace. No bank transfer, card charge, or refund will be sent.','amber'):''}<div class="field"><label for="a-action-reason">${isAccount?'Reason for account change':kind==='non-delivery'?'What happened?':'Review notes'}</label><textarea id="a-action-reason" name="reason" rows="3" minlength="5" maxlength="500" required placeholder="Add a clear reason for this decision…"></textarea></div>${isFinance||kind==='non-delivery'?`<label class="a-dialog-check"><input type="checkbox" name="reviewed" required><span>${kind==='non-delivery'?'I have reviewed the delivery and confirmed it was not made.':kind==='payout'?'I have reviewed delivery completion, the assigned driver, and the held payment.':'I have reviewed non-delivery or cancellation and verified that funds are held.'}</span></label>`:''}<div class="a-form-error" role="alert" hidden></div></div><footer class="a-dialog-actions"><button type="button" class="btn outline" id="a-action-cancel">Cancel</button><button type="submit" class="btn">${config[2]}</button></footer></form>`;
 document.body.append(dialog);const close=()=>{dialog.close();dialog.remove()};dialog.querySelector('.a-dialog-close').onclick=close;dialog.querySelector('#a-action-cancel').onclick=close;dialog.addEventListener('cancel',()=>dialog.remove());dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const fd=new FormData(event.currentTarget),reason=String(fd.get('reason'));
  try{
   if(isAccount)setAccountAccess(localStorage,id,kind==='remove-account',reason);
   else if(kind==='non-delivery')reviewNonDelivery(localStorage,id,reason);
   else if(kind==='capture')recordDemoPayment(localStorage,id,reason);
   else approveDecision(localStorage,id,kind,{reason,reviewed:fd.has('reviewed'),amount:job.total});
   close();refresh();helpers.toast(kind==='payout'?'Driver payment approved in the demo.':kind==='refund'?'Customer refund approved in the demo.':kind==='non-delivery'?'Non-delivery recorded.':kind==='capture'?'Sample payment recorded.':kind==='remove-account'?'Account access removed.':'Account access restored.');
  }catch(error){const box=dialog.querySelector('.a-form-error');box.hidden=false;box.textContent=error.message;}
 };dialog.showModal();
}
function handleClick(event){const button=event.target.closest('[data-admin-action]');if(!button)return;
 if(button.dataset.adminAction==='menu'){const app=$('.admin-app');app.classList.toggle('menu-open');$('.a-menu')?.setAttribute('aria-expanded',app.classList.contains('menu-open'));return}
 actionDialog(button.dataset.adminAction,button.dataset.id);
}
